"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search-api", "uid": "uid-deployment-search-api"},
    "params": {
        "container": "app",
        "readiness": {
            "timeoutSeconds": 5
        },
        "startup": {
            "initialDelaySeconds": 5,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Extend readiness probe timeout to 5s and add startup probe with 5s timeout and 5s initial delay to prevent premature liveness probe failures",
    "rationale": "Current readiness probe timeout (1s) and liveness probe timeout (1s) are too short for application startup. Startup probe is missing, so adding it with appropriate delays and timeouts will prevent premature failures. Readiness probe timeout is increased to 5s to match the 5s timeout for liveness probe, ensuring consistency and allowing the application to respond properly before timing out.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states"],
    "cited_predicates": ["probe_timeouts", "probe_kills", "killed_during_startup"]
}
